/** Only expose diagnostic details generated by our code. Provider bodies may contain user data. */
export class PresentationProviderError extends Error {
  readonly status: number;
  constructor(status: number) { super(`OpenAI presentation request failed (HTTP ${status}).`); this.status = status; }
}
export function presentationStatus(error: unknown) {
  return error instanceof PresentationProviderError && [400,401,402,403,404,422,429].includes(error.status) ? error.status : 502;
}
export function presentationFailure(error: unknown) {
  if (error instanceof PresentationProviderError) return error.message;
  if (error instanceof Error && ['TimeoutError', 'AbortError'].includes(error.name)) return 'The presentation request timed out.';
  if (error instanceof Error && ['Invalid topic outline','Topic outline has insufficient detail','Topic outline has insufficient visible area','Incomplete presentation response','Presentation response exceeded its size limit'].includes(error.message)) return error.message;
  return 'The presentation response could not be validated.';
}
/** One bounded, structured OpenAI call per reserved presentation stage. */
export async function presentationJson(key: string, instructions: string, input: unknown, name: string, schema: object, signal: AbortSignal, options: {model:string;maxTokens:number} = {model:'gpt-5.4-mini',maxTokens:5000}): Promise<unknown> {
  const response = await fetch('https://api.openai.com/v1/responses', {
    method: 'POST', signal,
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: options.model, store: false, stream: false, max_output_tokens: options.maxTokens,
      instructions, input: JSON.stringify(input), tools: [],
      text: { format: { type: 'json_schema', name, strict: true, schema } },
    }),
  });
  if (!response.ok || !response.body) {
    await response.body?.cancel();
    throw new PresentationProviderError(response.status);
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let bytes = 0, text = '';
  try {
    while (true) {
      const chunk = await reader.read();
      if (chunk.done) break;
      bytes += chunk.value.length;
      if (bytes > 256 * 1024) throw new Error('Presentation response exceeded its size limit');
      text += decoder.decode(chunk.value, { stream: true });
    }
    const result = JSON.parse(text + decoder.decode());
    if (result.status !== 'completed' || !Array.isArray(result.output)) throw new Error('Incomplete presentation response');
    const parts: string[] = [];
    for (const item of result.output) {
      if (item.type !== 'message' || !Array.isArray(item.content)) continue;
      for (const part of item.content) if (part.type === 'output_text' && typeof part.text === 'string') parts.push(part.text);
    }
    if (!parts.length) throw new Error('Incomplete presentation response');
    return JSON.parse(parts.join(''));
  } finally { await reader.cancel().catch(() => {}); }
}
